export const BODY: string = "\n<p>ثلاثة أرقام تسيطر على نماذج رفع الصور: 50 كيلوبايت و100 كيلوبايت و200 كيلوبايت. تبدو متقاربة، لكنها تفعل أشياء مختلفة جدًا بصورتك.</p>\n<p>اختيار الرقم الخاطئ يعني إما فشل الرفع أو التضحية بجودة دون داعٍ. والاختيار الصحيح يعني صورة تمر من أول مرة وتبدو جيدة.</p>\n<p>هذه المقارنة توضح ماذا يفعل كل حجم بالصورة، وأين ينتمي كل واحد، وكيف تختار بسرعة دون تخمين.</p>\n<h2 id=\"the-short-answer\">الإجابة المختصرة</h2>\n<p>الإجابة المختصرة: استخدم أكبر حجم تسمح به بوابتك. 50 كيلوبايت للنماذج الصارمة، و100 كيلوبايت للاستخدام العام، و200 كيلوبايت عندما تهم الجودة أكثر من الحجم.</p>\n<p>القاعدة بهذه البساطة لأن كل قفزة في الحجم تشتري تفاصيل حقيقية. الفرق بين 50 و100 كيلوبايت واضح للعين، وبين 100 و200 أوضح في التفاصيل الدقيقة.</p>\n<h2 id=\"what-50kb-looks-like\">كيف تبدو 50 كيلوبايت؟</h2>\n<p>عند 50 كيلوبايت، يبقى الوجه مميزًا والمستند مقروءًا، لكن التفاصيل الدقيقة تتلاشى. الشعر يفقد نسيجه، وحواف القماش تصبح أنعم.</p>\n<p>هذا الحجم مخصص للنماذج الحكومية ولوحات الامتحانات وبوابات التوظيف. هناك يكون اجتياز الحد أهم من الكمال البصري.</p>\n<h2 id=\"what-100kb-looks-like\">كيف تبدو 100 كيلوبايت؟</h2>\n<p>عند 100 كيلوبايت، تستعيد الصورة كثيرًا من تفاصيلها. الشعر والنظارات وحواف القماش تبدو أنظف، والنص الصغير يبقى مقروءًا في معظم الحالات.</p>\n<p>لهذا يعتبر 100 كيلوبايت النقطة المثالية لصور الملفات الشخصية والمدونات والبريد الإلكتروني. توازن جيد بين الحجم والجودة.</p>\n<h2 id=\"what-200kb-looks-like\">كيف تبدو 200 كيلوبايت؟</h2>\n<p>عند 200 كيلوبايت، تبدو معظم الصور مطابقة للأصل تقريبًا بأحجام العرض العادية. لا يلاحظ معظم الناس أي فرق دون تكبير الصورة.</p>\n<p>لهذا تفضل المدونات والمتاجر هذا الحجم. يشتري وضوحًا حقيقيًا بسعر تحميل ما زال خفيفًا على أي اتصال.</p>\n<h2 id=\"side-by-side\">جنبًا إلى جنب: الصورة نفسها بثلاثة أحجام</h2>\n<p>خذ الصورة نفسها واضغطها إلى الأحجام الثلاثة، ثم قارنها جنبًا إلى جنب. عند 50 كيلوبايت تلاحظ النعومة فورًا في الشعر والخلفيات المزدحمة.</p>\n<p>عند 100 كيلوبايت تختفي معظم النعومة، وعند 200 كيلوبايت يصبح الفرق عن الأصل شبه معدوم. هذه المقارنة العملية تعلّم عينك أكثر من أي جدول أرقام.</p>\n<h2 id=\"file-size-and-dimensions\">حجم الملف ليس كل شيء</h2>\n<p>حجم الملف ليس كل شيء. صورة 200 كيلوبايت بأبعاد صغيرة قد تبدو أسوأ من صورة 100 كيلوبايت بأبعاد أكبر، لأن الأبعاد تحدد التفاصيل المتاحة أصلًا.</p>\n<p>فكّر في الأمر كميزانية: الأبعاد تحدد كمية التفاصيل، وحجم الملف يحدد جودة حفظها. التوازن بينهما أهم من الرقم وحده.</p>\n<h2 id=\"which-size-for-which-job\">أي حجم لأي مهمة؟</h2>\n<p>للنماذج الصارمة استخدم <a href=\"/ar/daght-as-sura-ila-50kb/\">ضاغط 50 كيلوبايت</a>. وللصور الشخصية والمدونات استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a>.</p>\n<p>وللصور التي تُعرض كبيرة على موقعك، استخدم <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a>، وللحدود غير المعتادة جرّب <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>.</p>\n<h2 id=\"format-effects\">كيف تغيّر الصيغة المقارنة؟</h2>\n<p>الصيغة تغيّر المقارنة كاملة. JPG يتفوق للصور الفوتوغرافية، وWebP يتفوق عليه بهامش صغير، بينما PNG يفشل مع الصور عند الأحجام الصغيرة.</p>\n<p>لذلك لا تقارن الأحجام دون تثبيت الصيغة. صورة PNG بوزن 200 كيلوبايت قد تبدو أسوأ من صورة JPG بوزن 100 كيلوبايت.</p>\n<h2 id=\"loading-speed\">وماذا عن سرعة تحميل الصفحة؟</h2>\n<p>كل كيلوبايت إضافي يكلّف وقت تحميل. صفحة فيها عشر صور بوزن 200 كيلوبايت تحمل أبطأ بكثير من الصفحة نفسها بصور 50 كيلوبايت.</p>\n<p>على شبكات الجوال البطيئة يصبح الفرق ملموسًا. لذلك يفضل أصحاب المواقع 100 كيلوبايت للصور العادية و200 للصور الرئيسية فقط.</p>\n<h2 id=\"decision-framework\">إطار قرار في دقيقة واحدة</h2>\n<p>اسأل نفسك سؤالين: ما حد البوابة، وأين ستُعرض الصورة؟ الحد يحدد السقف، ومكان العرض يحدد الحد الأدنى من الجودة.</p>\n<p>إذا لم يوجد حد، فاختر 100 كيلوبايت للصور العادية و200 للصور الكبيرة. القاعدة بسيطة وتعمل في معظم الحالات.</p>\n<ul>\n<li>هل تفرض البوابة حدًا أقصى؟ التزم به أولًا.</li>\n<li>هل ستُعرض الصورة كبيرة؟ اختر 200 كيلوبايت.</li>\n<li>هل هي صورة ملف شخصي؟ يكفي 100 كيلوبايت.</li>\n<li>هل الاتصال بطيء لدى جمهورك؟ انزل إلى 50 كيلوبايت.</li>\n<li>هل النص مهم في الصورة؟ حافظ على الأبعاد كبيرة.</li>\n</ul>\n<h2 id=\"when-to-use-100kb-instead\">متى تنتقل من 50 إلى 100 كيلوبايت؟</h2>\n<p>إذا كانت بوابتك تقبل 100 كيلوبايت، فلا تضغط إلى 50 دون سبب. الانتقال من 50 إلى 100 يشتري وضوحًا ملحوظًا في الشعر والتفاصيل.</p>\n<p>استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> عندما يكون الحد مرنًا. ستحصل على صورة أجمل دون أي مخاطرة في الرفع.</p>\n<h2 id=\"quality-vs-dimensions\">الجودة مقابل الأبعاد: التوازن الحقيقي</h2>\n<p>الجودة والأبعاد توازن واحد. خفض الجودة يحافظ على حجم الصورة، بينما تقليص الأبعاد يقلل التفاصيل المتاحة من الأساس.</p>\n<p>ابدأ بخفض الجودة أولًا بالحجم الكامل. ولا تقلّص الأبعاد إلا عندما لا تكفي الجودة وحدها للوصول إلى الحد.</p>\n<h2 id=\"colour-banding\">شرائط اللون وكيف تتجنبها</h2>\n<p>شرائط اللون تظهر عندما يضغط التدرج الناعم، مثل السماء أو الجدران، إلى حجم صغير جدًا. تتحول التدرجات إلى خطوط واضحة.</p>\n<p>لتجنبها، اترك حجمًا أكبر قليلًا للتدرجات، أو استخدم WebP الذي يتعامل مع التدرجات أفضل من JPG عند الأحجام الصغيرة.</p>\n<h2 id=\"choosing-between-the-three\">طريقة عملية للاختيار بين الأحجام الثلاثة</h2>\n<p>الطريقة العملية: اضغط نسختك إلى الأحجام الثلاثة واحتفظ بها. ثم افتحها على الشاشة التي سيشاهدها جمهورك وقارنها بعينك.</p>\n<p>ستكتشف بسرعة أن 100 كيلوبايت يكفي لمعظم الاستخدامات، وأن 200 للصور التي تستحق أن تُعرض كبيرة.</p>\n<h2 id=\"future-proofing\">كيف تجهّز صورك المضغوطة للمستقبل</h2>\n<p>احتفظ دائمًا بالملف الأصلي عالي الجودة. حدود البوابات تتغير، وقد تحتاج نسخة أكبر لاحقًا، والملف المضغوط لا يمكن تكبيره دون خسارة.</p>\n<p>سمِّ نسخك المضغوطة حسب الحجم، مثل sora-100kb.jpg. التسمية الواضحة تمنع استخدام النسخة الخاطئة في النموذج الخاطئ.</p>\n<h2 id=\"upload-speeds\">سرعات الرفع والاتصالات البطيئة</h2>\n<p>سرعات الرفع مهمة عندما ترسل صورًا كثيرة. عشر صور بوزن 200 كيلوبايت تعني رفع ميغابايتين، بينما عشر صور بوزن 50 كيلوبايت تعني نصف ميغابايت فقط.</p>\n<p>على الاتصالات البطيئة، قد يعني الفرق دقائق من الانتظار. اضغط إلى أصغر حجم مقبول عندما تكون الشبكة بطيئة.</p>\n<h2 id=\"printing-50kb\">هل يمكن طباعة صورة 50 كيلوبايت؟</h2>\n<p>طباعة صورة 50 كيلوبايت ممكنة، لكن لا تتوقع جودة عالية. الطباعة تحتاج بكسلات أكثر بكثير من الشاشة، والصورة الصغيرة ستظهر باهتة على الورق.</p>\n<p>للطباعة، استخدم الملف الأصلي دائمًا. النسخ المضغوطة مخصصة للشاشات والنماذج الإلكترونية، لا للورق.</p>\n<h2 id=\"accessibility\">إمكانية الوصول: كيف تجعل الصور المضغوطة تناسب الجميع</h2>\n<p>الصور المضغوطة تعمل للجميع عندما تحافظ على تباين جيد ونص بديل واضح. الضغط لا يمنع قارئات الشاشة من قراءة النص البديل.</p>\n<p>تجنب وضع نص مهم داخل الصورة نفسها عند الأحجام الصغيرة، لأن النص قد يصبح غير مقروء. اكتب النص المهم في الصفحة لا في الصورة. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-50kb/\">الدليل الكامل لضغط الصورة إلى 50 كيلوبايت</a> و<a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-50kb/\">كيفية ضغط صورة إلى 50 كيلوبايت</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل 100 كيلوبايت أفضل بضعفين من 50 كيلوبايت؟","answer":"ليس بالضرورة. عند 100 كيلوبايت تحصل على تفاصيل أوضح، لكن الفرق يصغر كلما كبر الحجم. بعد 200 كيلوبايت يصبح التحسن غير ملحوظ لمعظم المشاهدات على الشاشة."},{"question":"هل تستطيع البوابة أن تكتشف أن صورتي تزن 51 كيلوبايت بدل 50؟","answer":"نعم، تستطيع البوابات ذلك. تفحص عدد البايتات بدقة، فملف 51 كيلوبايت يُرفض بينما ملف 49 كيلوبايت يجتاز. لذلك استهدف دائمًا أقل بقليل من الحد."},{"question":"ما الحجم الذي أستخدمه لصورة ملفي الشخصي في لينكدإن؟","answer":"صورة 100 كيلوبايت خيار آمن لصورة الملف الشخصي في لينكدإن. تبدو واضحة على الشاشات العادية وتحمّل بسرعة. وإذا كان الملف الأصلي أكبر، فاضغطه إلى 100 كيلوبايت دون تردد."},{"question":"هل يعني الملف الأكبر دائمًا صورة تبدو أفضل؟","answer":"غالبًا نعم، لكن ليس دائمًا. ملف أكبر يحمل تفاصيل أكثر، لكن إذا كان المصدر ضبابيًا أصلًا فلن يصلحه الحجم. الجودة تبدأ من الصورة الأصلية لا من حجم الملف."},{"question":"لماذا تبدو لقطة شاشتي أسوأ عند 50 كيلوبايت من صورتي الشخصية؟","answer":"لأن لقطات الشاشة تحمل نصًا وحوافًا حادة ومساحات مسطحة، وهي أصعب على الضغط من الوجوه والتدرجات الناعمة. النص الصغير يفقد حدته بسرعة عند الأحجام الصغيرة."},{"question":"إذا سمح نموذجي بـ200 كيلوبايت، فهل هناك سبب لاستخدام 50 كيلوبايت؟","answer":"لا، إذا كان الحد 200 كيلوبايت فاستخدمه. الملف الأكبر يحافظ على تفاصيل أكثر، ولا فائدة من ضغط الصورة أكثر من المطلوب. اضغط إلى أكبر حجم تسمح به البوابة."}];
